const b = $json.body || $json;

const nombre   = (b['nombre']      || '').toString().trim();
const email    = (b['email']       || '').toString().trim();
const telefono = (b['telefono']    || '').toString().trim();
const zip      = (b['ZipCode']     || '').toString().trim();
const producto = (b['Product']     || '').toString().trim();
const servicio = (b['Service']     || '').toString().trim();
const mensaje  = (b['Message']     || '').toString().trim();
const fecha    = (b['Fecha']       || new Date().toLocaleDateString('es-US',{timeZone:'America/New_York'})).toString().trim();

// Build shipment details from all 5 rows
const filas = [
  { cant: b['Cantidad'],  det: b['detalles'],  l: b['Length'],  w: b['Width'],  h: b['height'],  p: b['Weightaprox']  },
  { cant: b['Cantidad2'], det: b['Detalles2'], l: b['Length2'], w: b['Width2'], h: b['height2'], p: b['Weightaprox2'] },
  { cant: b['Cantidad3'], det: b['Detalles3'], l: b['Length3'], w: b['Width3'], h: b['height3'], p: b['Weightaprox3'] },
  { cant: b['Cantidad4'], det: b['Detalles4'], l: b['Length4'], w: b['Width4'], h: b['height4'], p: b['Weightaprox4'] },
  { cant: b['Cantidad5'], det: b['Detalles5'], l: b['Length5'], w: b['Width5'], h: b['height5'], p: b['Weightaprox5'] },
];

const lineas = filas
  .filter(f => f.det || f.l)
  .map(f => `${f.cant||'1'}x ${f.det||'item'} — ${f.l||'?'}×${f.w||'?'}×${f.h||'?'} in / ${f.p||'?'} lbs`);

const detalles_embarque = lineas.join('\n') || 'Sin dimensiones';

const resumen = [
  `📦 Producto: ${producto} / ${servicio}`,
  `📐 Detalles:\n${detalles_embarque}`,
  mensaje ? `💬 Notas: ${mensaje}` : ''
].filter(Boolean).join('\n');

const fecha_captura = new Date().toLocaleDateString('es-US', {timeZone:'America/New_York'});

return [{
  json: {
    // Para Leads Sheet
    nombre,
    email,
    telefono,
    direccion: `Zip: ${zip}`,
    web: '',
    rating: '',
    fecha_captura,
    correo_enviado: '0',
    fecha_c1: '', fecha_c2: '', fecha_c3: '',
    estado_email: 'activo',
    estado: 'Cotización Web',
    nicho: 'cotizacion-web',
    // Para Airtable
    zip, producto, servicio,
    mensaje: resumen,
    fecha_solicitud: fecha,
  }
}];

// Formulario de la web (CF7) → CRM de G54 (27-oct). Crea o actualiza el trato (upsert de G54 por teléfono
// o, sin teléfono, por correo) con origen "web" y deja una nota con el detalle del pedido.
// Si G54 falla, el formulario igual responde OK. Desde el 31-oct el CRM es el único lugar donde queda el lead (se sacó el Google Sheet).
const BASE = 'https://apigrowth.mdarthurdigital.com';
const AGENT = 'Bearer <G54_AGENT_TOKEN — ver .secrets.local.md>';
const COMPANY_ID = 1; // Crating Express: este flujo es solo del formulario de cratingexpress.com
const f = $('🔧 Formatear Datos').first().json;

const limpio = (v, max = 200) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f]/g, ' ').trim().slice(0, max);
const correo = limpio(f.email, 150).toLowerCase();
const telOriginal = String(f.telefono || '').trim();
let telDig = telOriginal.replace(/\D/g, '');
// 10 dígitos sin código de país = número de EE. UU. (el formulario es de Miami): se agrega el 1.
if (telDig.length === 10 && !telOriginal.startsWith('+')) telDig = '1' + telDig;
const telefono = telDig.length >= 8 && telDig.length <= 15 ? '+' + telDig : '';
const correoValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo);
if (!correoValido && !telefono) return [{ json: { ok: false, motivo: 'el formulario no trae correo ni teléfono válidos' } }];

const detalle = [
  'Pedido de cotización desde el formulario de la web' + (f.fecha_solicitud ? ' (' + limpio(f.fecha_solicitud, 40) + ')' : '') + '.',
  f.zip ? 'Zip: ' + limpio(f.zip, 20) + '.' : '',
  telOriginal && !telefono ? 'Teléfono escrito: ' + limpio(telOriginal, 40) + '.' : '',
  limpio(f.mensaje, 1500),
].filter(Boolean).join('\n');

const payload = {
  company_id: COMPANY_ID,
  nombre: limpio(f.nombre, 120) || correo || telefono,
  ...(telefono ? { telefono } : {}),
  ...(correoValido ? { email: correo } : {}),
  origen: 'web',
  temperatura: 'medio',
  tags: ['origen:formulario-web', 'cf7'],
  notas: detalle,
};
if ($('📥 Webhook CF7').first().json.body?.dry_run === true) return [{ json: { ok: true, dry_run: true, payload } }];

let deal = null;
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/agent/crm/leads',
    headers: { Authorization: AGENT, Accept: 'application/json' }, body: payload, json: true, timeout: 15000 });
  deal = (r && (r.deal || r.data)) || null;
} catch (e) {
  return [{ json: { ok: false, motivo: 'G54 no guardó el trato: ' + String(e.message || e).slice(0, 200) } }];
}
if (!deal || !deal.id) return [{ json: { ok: false, motivo: 'G54 respondió sin trato' } }];
if (Number(deal.company_id) !== COMPANY_ID) return [{ json: { ok: false, motivo: 'el trato quedó en otra empresa', deal_id: deal.id } }];

let nota = false;
try {
  await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/agent/crm/leads/' + deal.id + '/activities',
    headers: { Authorization: AGENT, Accept: 'application/json' },
    body: { tipo: 'nota', contenido: detalle }, json: true, timeout: 15000 });
  nota = true;
} catch (e) { nota = false; }
return [{ json: { ok: true, deal_id: deal.id, nota } }];
